import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))

        x = []
        for _ in range(n):
            x.append(int(next(iterator)))

        segments = []
        for _ in range(m):
            l = int(next(iterator))
            r = int(next(iterator))
            segments.append((l, r))

    except StopIteration:
        return

    # Sort points and keep track of original indices
    # We need to assign colors to the original points
    # Let's create a list of (coordinate, original_index)
    points_with_idx = sorted([(x[i], i) for i in range(n)])

    # We will determine colors based on the sorted order of points
    # Assign alternating colors: 0, 1, 0, 1, ...
    # This ensures that in any interval, the difference between counts of 0s and 1s is at most 1

    colors_sorted = [0] * n
    for i in range(n):
        colors_sorted[i] = i % 2

    # Map back to original indices
    result = [0] * n
    for i in range(n):
       coord, orig_idx = points_with_idx[i]
       result[orig_idx] = colors_sorted[i]

    # Verify the solution just to be safe (though mathematically it should work)
    # If verification fails, we output -1 (though for this problem structure, 
    # alternating assignment always works)

    valid = True
    for l, r in segments:
        r_count = 0
        b_count = 0
        for i in range(n):
            if l <= x[i] <= r:
                if result[i] == 0:
                    r_count += 1
                else:
                    b_count += 1
        if abs(r_count - b_count) > 1:
            valid = False
            break

    if valid:
        print(*(result))
    else:
        print(-1)

if __name__ == '__main__':
    solve()
